import {isSpeechDemo,canSynthesizeEntry} from './js/speech-availability.js?v=19-speech-on';
import {CONFIG} from './config.js?v=19-speech-on';
import {ensureWriting,writingFields,WRITING_TYPES,writingTypeName,clozeTokens,validClozeBlanks,clozeSegments} from './js/writing-model.js';
import {ensureSpeaking,speakingFields} from './js/speaking-model.js';
import {repairLessonSpelling} from './js/lesson-corrections.js';
import {ensureAssessments,assessmentFields,questionHasContent} from './js/assessment-model.js';
import {ensureGrammarExamples,grammarEntries} from './js/grammar-model.js';
import {bookStyles,mountBook,makeBookData,buildBookHTML,audioEntries,audioIsCurrent,resolveAudio,contentIssues} from './js/student-book.js?v=19-speech-on';
import {normalizeNative,normalizeUnitNative} from './js/native-text.js';
import {normaliseAudioBlob,playbackErrorMessage} from './js/audio-format.js';
import {translateText,synthesizeSpeech} from './js/api.js?v=19-speech-on';
import {TeacherRecorder} from './js/teacher-recorder.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), topics=[['intro','自我介紹','初級'],['routine','日常作息','初級'],['hobby','興趣與偏好','初級'],['family','跟家人的互動','初級'],['visit','拜訪親人','中級'],['weather','談論天氣','中級'],['shop','在商店買東西','中級'],['directions','問路','中級']];
const langs=window.LANGUAGES;let step=1,topic='intro',busy=false,selected=null,saveTimer,db,recordingId=null,recordingStarted=0,recordingTimer;
const recorder=new TeacherRecorder();const grammarOpen=new Map(),questionOpen=new Map(),vocabularyOpen=new Map(),speakingOpen=new Map(),writingOpen=new Map();
function fresh(){const ethnicity=Object.keys(langs)[0];return {schemaVersion:'1.0.0',id:uid(),status:'draft',metadata:{title:'',language:{ethnicity,dialect:langs[ethnicity].languages[0][1],voice:langs[ethnicity].voices[0][1]},objectives:'',homePractice:'',updatedAt:new Date().toISOString()},assets:{},context:{sceneImageAssetId:null,dialogues:Array.from({length:6},(_,i)=>({id:uid(),speaker:i%2?'角色乙':'角色甲',text:{indigenous:'',zhHant:''}}))},languageFocus:{vocabulary:[],grammar:[{id:uid(),title:'',pattern:'',explanation:'',example:{indigenous:'',zhHant:''},sourceDialogueIds:[]}]},assessments:{reading:{items:[]},listening:{items:[]},speaking:{items:[]},writing:{items:[]}}};}
let unit=fresh(),bookView=null;
unit.languageFocus.grammar.forEach(ensureGrammarExamples);ensureAssessments(unit);
const req=r=>new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function init(){try{const r=indexedDB.open('unit-language-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts');db=await req(r);const saved=await req(db.transaction('drafts').objectStore('drafts').get('current'));if(saved){unit=validate(saved);if(repairLessonSpelling(unit))save();topic=unit.metadata.topicId||scene().match(/scenes\/([a-z]+)-/)?.[1]||'intro';}$('#saved').textContent=saved?'已開啟上次草稿':'尚未編輯';}catch(e){$('#saved').textContent='草稿未能開啟：'+e.message;}renderTeacherStep();}
function save(){unit.metadata.updatedAt=new Date().toISOString();$('#saved').textContent='保存中…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{if(!db){$('#saved').textContent='請下載編輯檔備份';return}const tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').put(structuredClone(unit),'current');tx.oncomplete=()=>$('#saved').textContent='已保存於這台電腦 '+new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});tx.onerror=()=>$('#saved').textContent='保存失敗，請下載編輯檔';},350)}
function notify(text){const previewProgress=$('#modal .preview-progress');if(previewProgress){previewProgress.hidden=false;previewProgress.textContent=text;}$('#status').style.display='block';$('#status').textContent=text;if(!busy)setTimeout(()=>{if(!busy)$('#status').style.display='none'},6500)}
function opt(items,value){return items.map(([label,v])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label.replaceAll('_',' · '))}</option>`).join('')}
function scene(){return unit.assets[unit.context.sceneImageAssetId]?.src||''}
function renderTeacherStep(){unit.languageFocus.grammar.forEach(ensureGrammarExamples);ensureAssessments(unit);document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',+b.dataset.step===step);b.setAttribute('aria-current',+b.dataset.step===step?'step':'false')});selected=null;$('#view').innerHTML=step===1?contextView():step===2?vocabularyView():step===3?grammarView():step===6?speakingView():step===7?writingView():step===8?homeworkView():assessmentView(step===4?'reading':'listening');applySpeechAvailability();}
function contextView(){const l=unit.metadata.language,selectedScene=scene(),t=topics.find(t=>t[0]===topic)||topics[0];return `<section class="panel"><h2>語別與單元設定</h2><div class="language-fields"><label>語別<select id="ethnicity">${opt(Object.keys(langs).map(x=>[x,x]),l.ethnicity)}</select></label><div class="grid"><label>翻譯方言<select id="dialect">${opt(langs[l.ethnicity].languages,l.dialect)}</select></label><label>朗讀聲音<select id="voice">${opt(langs[l.ethnicity].voices,l.voice)}</select></label></div></div><label class="learning-objectives">學習目標<textarea rows="3" maxlength="2000" data-meta="objectives" placeholder="例如：能用族語詢問並回答自己與他人喜歡的活動。">${esc(unit.metadata.objectives||'')}</textarea></label><label class="unit-title">單元名稱<input data-meta="title" value="${esc(unit.metadata.title)}" placeholder="例如：一起去商店"></label></section><section class="panel"><div class="rowhead"><h2>情境圖片</h2><button data-action="upload">上傳自己的圖片</button></div><label>程度與主題<select id="topic">${['初級','中級'].map(level=>`<optgroup label="${level}">${topics.filter(t=>t[2]===level).map(([v,l])=>`<option value="${v}" ${v===topic?'selected':''}>${level} · ${l}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="gallery">${[0,1].map(i=>{const src=`assets/scenes/${topic}-${i}.jpg`;const active=selectedScene===src||unit.assets[unit.context.sceneImageAssetId]?.originalSrc===src;return `<button class="image-choice" data-scene="${src}" aria-pressed="${active}" aria-label="選擇${esc(t[1])}圖片 ${i+1}"><img src="${src}" alt="${esc(t[1])}情境 ${i+1}"><span>情境 ${i+1}</span><span class="image-check" aria-hidden="true">✓</span></button>`}).join('')}</div>${selectedScene&&!unit.assets[unit.context.sceneImageAssetId]?.originalSrc&&!selectedScene.startsWith('assets/')?`<div class="uploaded-scene"><img src="${esc(selectedScene)}" alt="老師上傳的情境圖片"><span>使用上傳圖片</span></div>`:''}<input type="file" id="image-upload" aria-label="上傳情境圖片" accept="image/png,image/jpeg,image/webp" hidden></section><section class="panel dialogue-panel"><div class="rowhead"><h2>雙語對話</h2><span>${unit.context.dialogues.length} / 8 句</span></div><p class="muted">編寫 6–8 句對話，翻譯後可直接修改文字。</p>${unit.context.dialogues.map((d,i)=>dialogueView(d,i)).join('')}<div class="tools"><button data-action="add-dialogue" ${unit.context.dialogues.length>=8?'disabled':''}>新增一句</button><button class="primary" data-step="2">下一關：整理生詞</button></div></section>`;}
function audioState(d,kind='dialogue'){if(!d.audio)return '';const a=unit.assets[d.audio.assetId];if(!a)return '';const outdated=d.audio.textSnapshot!==fields(kind,d).native||d.audio.ethnicity!==unit.metadata.language.ethnicity||(d.audio.source==='tts'&&d.audio.voice!==unit.metadata.language.voice);return `<div class="sentence-audio"><small>${d.audio.source==='recording'?'老師錄音':d.audio.source==='upload'?'上傳音檔':'合成語音'}${outdated?' · 文字或語別已變更，請重新準備聲音':''}</small><audio controls preload="none" aria-label="${kind==='vocab'?'試聽這個生詞':'試聽這句對話'}" src="${esc(a.src)}"></audio></div>`;}
function dialogueView(d,i){return `<article class="dialogue" data-id="${d.id}"><div class="rowhead"><h3>第 ${i+1} 句</h3><button class="delete-line" aria-label="刪除第 ${i+1} 句" data-action="remove-dialogue" ${unit.context.dialogues.length<=6?'disabled':''}>刪除</button></div><div class="dialogue-bubble"><div class="speaker-card"><svg aria-hidden="true" viewBox="0 0 48 48"><circle cx="24" cy="15" r="8"/><path d="M8 43v-6a16 16 0 0 1 32 0v6z"/></svg><label><span class="sr-only">說話角色</span><input data-field="speaker" aria-label="第 ${i+1} 句角色" value="${esc(d.speaker)}"></label></div><div class="sentence-fields"><label>華語<textarea rows="1" data-field="zhHant" placeholder="輸入華語意思">${esc(d.text.zhHant)}</textarea></label><label>族語<textarea rows="1" data-field="indigenous" data-select="${d.id}" placeholder="輸入族語對話">${esc(d.text.indigenous)}</textarea></label><div class="word-selection" hidden><span class="selected-word"></span><button data-action="add-vocab">加入生詞</button></div><div class="tools compact"><button data-action="toNative">華語翻族語</button><button data-action="toChinese">族語翻華語</button><button data-action="synthesize">合成語音</button><button data-action="record">自己錄音</button></div><div class="recording-feedback" role="status" hidden></div><div class="media-slot">${audioState(d)}</div></div></div></article>`}
function vocabularyView(){return `<section class="panel vocabulary-panel"><div class="section-toolbar"><div><h2>重點生詞</h2><p class="muted">從對話加入或手動新增，最多 10 個。</p></div><span>${unit.languageFocus.vocabulary.length} / 10 個</span><button data-action="batch-vocabulary" ${unit.languageFocus.vocabulary.length?'':'disabled'}>批次合成生詞語音</button><button data-action="manual-vocab" ${unit.languageFocus.vocabulary.length>=10?'disabled':''}>手動新增生詞</button></div>${unit.languageFocus.vocabulary.length?unit.languageFocus.vocabulary.map((v,i)=>`<details class="grammar-fold" data-vocabulary-toggle="${v.id}" ${vocabularyOpen.get(v.id)!==false?'open':''}><summary>生詞 ${i+1}<span class="vocabulary-fold-title">${esc(v.term||'尚未填寫')}</span></summary><article class="focus-card vocabulary-card" data-kind="vocab" data-id="${v.id}"><div class="rowhead"><h3>生詞 ${i+1}</h3><button class="delete-line" data-action="remove-vocab" aria-label="刪除生詞 ${i+1}">刪除</button></div><div class="grid"><label>族語單詞<input data-field="term" value="${esc(v.term)}"></label><label>華語詞義<input data-field="translation" value="${esc(v.translation)}"></label></div>${v.source?`<small>${sourceStatus(v)}</small>`:''}<div class="tools compact"><button data-action="toChinese">族語翻華語</button><button data-action="toNative">華語翻族語</button><button data-action="synthesize">合成語音</button><button data-action="record">自己錄音</button></div><div class="recording-feedback" role="status" hidden></div><div class="media-slot">${audioState(v,'vocab')}</div></article></details>`).join(''):'<p class="empty">尚未加入生詞。回到對話頁反白單詞，按「加入生詞」即可帶入。</p>'}</section><div class="step-footer"><button data-step="1">上一關：情境與對話</button><button class="primary" data-step="3">下一關：整理語法</button></div>`}
function courseExamples(g){return g.sourceDialogueIds.map(id=>{const d=unit.context.dialogues.find(d=>d.id===id);return d?`<div class="course-example"><p><span>華語</span>${esc(d.text.zhHant||'尚未填寫華語')}</p><p><span>族語</span>${esc(d.text.indigenous||'尚未填寫族語')}</p></div>`:''}).join('')||'<p class="muted">選擇課文中的對話，會帶入雙語例句。</p>'}
function grammarView(){return `<section class="panel grammar-panel"><div class="section-toolbar"><div><h2>重點語法</h2><p class="muted">整理 1–2 個句型，搭配課文與其他例句。</p></div><button data-action="add-grammar" ${unit.languageFocus.grammar.length>=2?'disabled':''}>新增語法點</button></div>${unit.languageFocus.grammar.map((g,i)=>`<details class="grammar-fold" data-grammar-toggle="${g.id}" ${grammarOpen.get(g.id)!==false?'open':''}><summary>語法 ${i+1}<span class="grammar-fold-title">${esc(g.title||'尚未命名')}</span></summary><article class="focus-card grammar-card" data-kind="grammar" data-id="${g.id}"><div class="rowhead"><h3>語法 ${i+1}</h3><button class="delete-line" data-action="remove-grammar" ${unit.languageFocus.grammar.length<=1?'disabled':''}>刪除語法</button></div><label>1. 語法名稱<input data-field="title" value="${esc(g.title)}" placeholder="例如：否定句"></label><fieldset><legend>2. 課文例句</legend><label><span class="sr-only">引用課文</span><select data-field="source" aria-label="引用課文"><option value="">選擇課文對話</option>${unit.context.dialogues.map((d,i)=>`<option value="${d.id}" ${g.sourceDialogueIds.includes(d.id)?'selected':''}>第 ${i+1} 句：${esc(d.text.indigenous||'尚未填寫族語')}</option>`).join('')}</select></label><div class="course-examples">${courseExamples(g)}</div></fieldset><label>3. 句型結構<textarea class="pattern-editor" data-field="pattern" rows="3" placeholder="可分行填寫不同結構">${esc(g.pattern)}</textarea></label><label>4. 說明<textarea data-field="explanation" placeholder="用簡單的話說明句型用法">${esc(g.explanation)}</textarea></label><fieldset class="extra-examples"><legend>5. 其他例句</legend>${ensureGrammarExamples(g).map((e,j)=>`<article class="example-editor" data-kind="example" data-id="${e.id}" data-grammar-id="${g.id}"><span class="example-number">例句 ${j+1}</span><label>族語<textarea rows="1" data-field="indigenous" aria-label="例句 ${j+1} 族語" placeholder="輸入族語例句">${esc(e.indigenous)}</textarea></label><label>華語<textarea rows="1" data-field="zhHant" aria-label="例句 ${j+1} 華語" placeholder="輸入華語意思">${esc(e.zhHant)}</textarea></label><div class="tools compact"><button data-action="toNative">華語翻族語</button><button data-action="toChinese">族語翻華語</button><button data-action="synthesize">合成句子語音</button><button data-action="record">自己錄音</button></div><div class="recording-feedback" role="status" hidden></div><div class="media-slot">${audioState(e,'example')}</div></article>`).join('')}</fieldset></article></details>`).join('')}</section><div class="step-footer"><button data-step="2">上一關：整理生詞</button><button class="primary" data-step="4">下一關：閱讀練習</button></div>`}
function lessonReference(){return `<details class="lesson-reference"><summary>查看本課對話</summary>${unit.context.dialogues.map((d,i)=>`<div class="reference-line"><small>第 ${i+1} 句 · ${esc(d.speaker)}</small><p>${esc(d.text.indigenous||'尚未填寫族語')}</p><p class="muted">${esc(d.text.zhHant)}</p></div>`).join('')}</details>`;}
function assessmentFieldView(field,label,kind){const audio=kind==='listening';return `<div class="assessment-field" data-id="${field.id}" data-kind="assessment-field"><label>華語<textarea rows="1" data-field="zhHant" aria-label="${esc(label)} 華語" placeholder="先輸入華語，也可直接編寫族語">${esc(field.zhHant)}</textarea></label><label>族語<textarea rows="1" data-field="indigenous" aria-label="${esc(label)} 族語" placeholder="輸入族語或使用翻譯">${esc(field.indigenous)}</textarea></label><div class="tools compact"><button data-action="toNative">華語翻族語</button><button data-action="toChinese">族語翻華語</button>${audio?'<button data-action="synthesize">合成語音</button><button data-action="record">自己錄音</button>':''}</div>${audio?`<input class="practice-audio-upload" type="file" accept="audio/*" aria-label="${esc(label)} 上傳音檔" hidden><div class="recording-feedback" role="status" hidden></div><div class="media-slot">${audioState(field,'assessment-field')}</div>`:''}</div>`;}
function assessmentView(kind){const name=kind==='reading'?'閱讀':'聽力',items=unit.assessments[kind].items;return `<section class="panel assessment-panel"><div class="section-toolbar"><div><h2>${name}練習</h2><p class="muted">${kind==='reading'?'依課文編寫題目，最多五題；每題三個選項，點選 ABC 指定正解。':'練習本課單詞與句型的聽力，每題一段音檔，搭配 ABC 選項。'}</p></div><span class="assessment-count">${items.length} / 5 題</span><button data-action="add-assessment" data-assessment="${kind}" ${items.length>=5?'disabled':''}>新增題目</button></div>${items.map((q,i)=>`<details class="question-fold" data-question-toggle="${q.id}" ${questionOpen.has(q.id)?(questionOpen.get(q.id)?'open':''):(i===0?'open':'')}><summary>第 ${i+1} 題<span class="question-fold-title">${esc(q.prompt.zhHant||q.prompt.indigenous||'尚未編寫')}</span></summary><article class="question-editor" data-kind="question" data-id="${q.id}" data-assessment="${kind}"><div class="rowhead"><h3>題目</h3><button class="delete-line" data-action="remove-assessment" ${items.length<=1?'disabled':''}>刪除此題</button></div>${assessmentFieldView(q.prompt,`${name}第 ${i+1} 題題目`,kind)}${q.options.map((o,j)=>`<section class="assessment-option"><label class="correct-option"><input type="radio" name="correct-${q.id}" value="${o.id}" data-correct-question="${q.id}" data-assessment="${kind}" ${q.answer.correctOptionId===o.id?'checked':''}><span>${'ABC'[j]}</span></label>${assessmentFieldView(o,`${name}第 ${i+1} 題選項 ${'ABC'[j]}`,'reading')}</section>`).join('')}</article></details>`).join('')}</section><div class="step-footer"><button data-step="${kind==='reading'?3:4}">上一關：${kind==='reading'?'整理語法':'閱讀練習'}</button>${kind==='reading'?'<button class="primary" data-step="5">下一關：聽力練習</button>':'<button class="primary" data-step="6">下一關：口說練習</button>'}</div>`;}
function sourceStatus(v){const d=unit.context.dialogues.find(d=>d.id===v.source.dialogueId),s=v.source.selection;return d&&d.text.indigenous.slice(s.start,s.end)===s.quote?'來源：第 '+(unit.context.dialogues.indexOf(d)+1)+' 句':'來源對話已變更，請重新核對此生詞。'}
function renderStudentView(){bookView?.destroy();$('#modal').classList.add('book-preview');$('#modal-content').innerHTML=`<div class="preview-toolbar"><span>互動課本預覽</span><button data-action="export-book">下載互動課本 HTML</button></div><p class="preview-progress" role="status" aria-live="polite" hidden></p><style>${bookStyles}</style><div id="book-preview-root" class="unit-book"></div><p class="preview-note">${!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED})?'語音合成暫停中。下載只使用既有音檔與老師錄音；灰色播放按鈕表示尚未準備音訊。':'灰色喇叭表示尚未準備音訊。下載時會補齊合成語音，並保留老師錄音。'}</p>`;bookView=mountBook($('#book-preview-root'),makeBookData(unit,{includeEmptyWriting:true}));$('#modal').showModal();}
function speakingView(){const items=ensureSpeaking(unit);return `<section class="panel speaking-panel"><div class="section-toolbar"><div><h2>口說練習</h2><p class="muted">${!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED})?'設定 1–5 題。可填寫族語題目並按「自己錄音」錄製聲音；學生聽完後錄音回答。':'設定 1–5 題。可填寫族語並合成題目語音，也可以直接錄製題目；學生聽完後錄音回答。'}</p></div><span>${items.length} / 5 題</span><button data-action="add-speaking" ${items.length>=5?'disabled':''}>新增口說題</button></div>${items.map((q,i)=>`<details class="question-fold" data-speaking-toggle="${q.id}" ${speakingOpen.has(q.id)?(speakingOpen.get(q.id)?'open':''):(i===0?'open':'')}><summary>第 ${i+1} 題<span class="question-fold-title">${esc(q.prompt.zhHant||q.prompt.indigenous||(q.prompt.audio?'老師錄製題目':'尚未編寫'))}</span></summary><article class="question-editor" data-kind="speaking-question" data-id="${q.id}"><div class="rowhead"><h3>題目語音</h3><button class="delete-line" data-action="remove-speaking" ${items.length<=1?'disabled':''}>刪除此題</button></div><div data-kind="speaking-field" data-id="${q.prompt.id}"><label>華語（選填）<textarea rows="1" data-field="zhHant" aria-label="口說第 ${i+1} 題華語">${esc(q.prompt.zhHant)}</textarea></label><label>族語題目<textarea rows="1" data-field="indigenous" aria-label="口說第 ${i+1} 題族語" placeholder="輸入題目後合成語音，或直接按自己錄音">${esc(q.prompt.indigenous)}</textarea></label><div class="tools compact"><button data-action="toNative">華語翻族語</button><button data-action="toChinese">族語翻華語</button><button data-action="synthesize">合成題目語音</button><button data-action="record">自己錄音</button></div><div class="recording-feedback" role="status" hidden></div><div class="media-slot">${audioState(q.prompt,'speaking-field')}</div></div></article></details>`).join('')}</section><div class="step-footer"><button data-step="5">上一關：聽力練習</button><button class="primary" data-step="7">下一關：寫作練習</button></div>`;}
function clozeControls(q){const selected=validClozeBlanks(q);return `<p class="muted">點選 1–2 個單詞挖空，再點一次即可取消。</p><div class="cloze-word-buttons">${clozeTokens(q.prompt.indigenous).map(t=>`<button data-action="toggle-cloze" data-blank-start="${t.start}" aria-pressed="${selected.some(b=>b.start===t.start)}">${esc(t.text)}</button>`).join('')||'<span class="muted">先輸入族語句子。</span>'}</div><p class="cloze-teacher-preview">學生看到：${clozeSegments(q).map(part=>part.blankId?'＿＿＿':esc(part.text)).join('')||'尚未填寫'}</p>`;}
function writingView(){const items=ensureWriting(unit);return `<section class="panel writing-panel"><h2>寫作練習</h2><p class="muted">回答問題、翻譯、填空，每種可設定 2–3 題。</p>${WRITING_TYPES.map(type=>{const group=items.filter(q=>q.type===type);return `<section class="writing-editor-group"><div class="rowhead"><h3>${writingTypeName(type)}</h3><span>${group.length} / 3 題</span><button data-action="add-writing" data-writing-type="${type}" ${group.length>=3?'disabled':''}>新增題目</button></div>${group.map((q,i)=>`<details class="question-fold" data-writing-toggle="${q.id}" ${writingOpen.has(q.id)?(writingOpen.get(q.id)?'open':''):(i===0?'open':'')}><summary>第 ${i+1} 題<span class="question-fold-title">${esc((type==='question'?q.prompt.indigenous:q.prompt.zhHant)||'尚未編寫')}</span></summary><article class="question-editor" data-kind="writing-question" data-id="${q.id}"><div class="rowhead"><h3>第 ${i+1} 題</h3><button class="delete-line" data-action="remove-writing" ${group.length<=2?'disabled':''}>刪除此題</button></div><div data-kind="writing-field" data-id="${q.prompt.id}">${type!=='question'?`<label>華語句子<textarea rows="2" data-field="zhHant" aria-label="${writingTypeName(type)}第 ${i+1} 題華語">${esc(q.prompt.zhHant)}</textarea></label>`:''}${type!=='translation'?`<label>${type==='question'?'族語問題':'族語完整句子'}<textarea rows="2" data-field="indigenous" aria-label="${writingTypeName(type)}第 ${i+1} 題族語">${esc(q.prompt.indigenous)}</textarea></label>`:''}</div>${type==='question'&&q.prompt.zhHant?`<details class="legacy-writing-note"><summary>原華語提示（舊草稿保留）</summary><p>${esc(q.prompt.zhHant)}</p></details>`:''}${type==='cloze'?`<div class="cloze-controls">${clozeControls(q)}</div>`:''}</article></details>`).join('')}</section>`;}).join('')}</section><div class="step-footer"><button data-step="6">上一關：口說練習</button><button class="primary" data-step="8">下一關：課後小練習</button></div>`;}
function modelFor(el){const row=el.closest('[data-id]');if(!row)return {};const kind=row.dataset.kind||'dialogue';const data=(kind==='vocab'?unit.languageFocus.vocabulary:kind==='grammar'?unit.languageFocus.grammar:kind==='example'?grammarEntries(unit):kind==='assessment-field'?[...assessmentFields(unit,'reading'),...assessmentFields(unit,'listening'),...speakingFields(unit)]:kind==='speaking-field'?speakingFields(unit):kind==='writing-question'?unit.assessments.writing.items:kind==='writing-field'?writingFields(unit):kind==='speaking-question'?unit.assessments.speaking.items:kind==='question'?[...unit.assessments.reading.items,...unit.assessments.listening.items]:unit.context.dialogues).find(x=>x.id===row.dataset.id);return {row,kind,data};}
function updateField(el){if(el.dataset.meta){unit.metadata[el.dataset.meta]=el.value;save();return}if(!el.dataset.field)return;const {kind,data}=modelFor(el);if(!data)return;const f=el.dataset.field;const nativeField=(kind==='dialogue'&&f==='indigenous')||(kind==='vocab'&&f==='term')||(kind==='grammar'&&f==='pattern')||(['example','assessment-field','speaking-field','writing-field'].includes(kind)&&f==='indigenous');const nativeChanged=nativeField&&fields(kind,data).native!==normalizeNative(el.value);if(nativeField){const start=el.selectionStart,end=el.selectionEnd;const normalized=normalizeNative(el.value);if(el.value!==normalized){el.value=normalized;if(start!==null)el.setSelectionRange(start,end)}}if(kind==='dialogue'){if(f==='speaker')data.speaker=el.value;else data.text[f]=el.value;}else if(kind==='vocab'||kind==='example'||kind==='assessment-field'||kind==='speaking-field'||kind==='writing-field'){data[f]=el.value}else if(f==='indigenous'||f==='zhHant')data.example[f]=el.value;else if(f==='source'&&kind==='question'){data.sourceDialogueIds=el.value?[el.value]:[];}else if(f==='source'){data.sourceDialogueIds=el.value?[el.value]:[];el.closest('[data-id]').querySelector('.course-examples').innerHTML=courseExamples(data);}else data[f]=el.value;if(kind==='vocab'&&f==='term'){const title=el.closest('[data-vocabulary-toggle]')?.querySelector('.vocabulary-fold-title');if(title)title.textContent=el.value||'尚未填寫';}if(kind==='grammar'&&f==='title'){const title=el.closest('.grammar-fold')?.querySelector('.grammar-fold-title');if(title)title.textContent=el.value||'尚未命名';}if(kind==='writing-field'){const q=unit.assessments.writing.items.find(q=>q.prompt===data);if(q?.type==='cloze'&&f==='indigenous'&&nativeChanged){q.blanks=[];const controls=el.closest('.question-editor').querySelector('.cloze-controls');if(controls)controls.innerHTML=clozeControls(q);}const title=el.closest('[data-writing-toggle]')?.querySelector('.question-fold-title');if(title)title.textContent=(q?.type==='question'?data.indigenous:data.zhHant)||'尚未編寫';}if(kind==='speaking-field'){const title=el.closest('[data-speaking-toggle]')?.querySelector('.question-fold-title');if(title)title.textContent=data.zhHant||data.indigenous||(data.audio?'老師錄製題目':'尚未編寫');}if(kind==='assessment-field'){const summary=el.closest('.question-fold')?.querySelector('.question-fold-title');const q=el.closest('.question-editor');const item=q&&unit.assessments[q.dataset.assessment].items.find(qi=>qi.id===q.dataset.id);if(summary&&item)summary.textContent=item.prompt.zhHant||item.prompt.indigenous||'尚未編寫';}if(nativeField)refreshSentenceAudio(data);if(kind==='dialogue'&&f==='indigenous'&&nativeChanged)clearWordSelections();save()}
document.addEventListener('toggle',e=>{if(e.target.matches('[data-vocabulary-toggle]'))vocabularyOpen.set(e.target.dataset.vocabularyToggle,e.target.open);if(e.target.matches('[data-grammar-toggle]'))grammarOpen.set(e.target.dataset.grammarToggle,e.target.open);if(e.target.matches('[data-writing-toggle]'))writingOpen.set(e.target.dataset.writingToggle,e.target.open);if(e.target.matches('[data-speaking-toggle]'))speakingOpen.set(e.target.dataset.speakingToggle,e.target.open);if(e.target.matches('[data-question-toggle]'))questionOpen.set(e.target.dataset.questionToggle,e.target.open);},true);
document.addEventListener('input',e=>updateField(e.target));
document.addEventListener('change',e=>{const el=e.target,l=unit.metadata.language;if(el.dataset.correctQuestion){const q=unit.assessments[el.dataset.assessment].items.find(q=>q.id===el.dataset.correctQuestion);q.answer.correctOptionId=el.value;save();return;}if(el.id==='ethnicity'){l.ethnicity=el.value;l.dialect=langs[el.value].languages[0][1];l.voice=langs[el.value].voices[0][1];save();renderTeacherStep()}else if(el.id==='dialect'){l.dialect=el.value;save()}else if(el.id==='voice'){l.voice=el.value;save();[...unit.context.dialogues,...unit.languageFocus.vocabulary,...grammarEntries(unit),...assessmentFields(unit,'listening'),...speakingFields(unit)].forEach(refreshSentenceAudio)}else if(el.id==='topic'){topic=el.value;unit.metadata.topicId=topic;save();renderTeacherStep()}else updateField(el)});
function clearWordSelections(){selected=null;document.querySelectorAll('.word-selection').forEach(el=>el.hidden=true);}
function captureWordSelection(){const el=document.activeElement;if(!el?.dataset?.select)return;if(el.selectionEnd<=el.selectionStart){clearWordSelections();return;}selected={dialogueId:el.dataset.select,start:el.selectionStart,end:el.selectionEnd,quote:el.value.slice(el.selectionStart,el.selectionEnd)};document.querySelectorAll('.word-selection').forEach(box=>{const active=box.closest('[data-id]').dataset.id===selected.dialogueId;box.hidden=!active;if(active){box.querySelector('.selected-word').textContent=selected.quote;const b=box.querySelector('button');b.disabled=false;b.textContent='加入生詞';}});}
document.addEventListener('selectionchange',captureWordSelection);
document.addEventListener('pointerup',captureWordSelection);
document.addEventListener('keyup',captureWordSelection);
document.addEventListener('select',captureWordSelection,true);
function addSelectedVocabulary(d){if(!selected||selected.dialogueId!==d.id||d.text.indigenous.slice(selected.start,selected.end)!==selected.quote)return notify('請先在族語欄反白選取單詞。');if(!selected.quote.trim())return notify('請選取單詞，不能只選空白。');const duplicate=unit.languageFocus.vocabulary.some(v=>v.term===selected.quote&&v.source?.dialogueId===d.id);if(!duplicate){if(unit.languageFocus.vocabulary.length>=10)return notify('生詞最多 10 個，請先刪除不需要的生詞。');unit.languageFocus.vocabulary.push({id:uid(),term:selected.quote,translation:'',source:{dialogueId:d.id,selection:{...selected,offsetUnit:'utf16'}}});save()}const button=document.querySelector(`[data-id="${d.id}"] .word-selection button`);if(button){button.textContent='已加入';button.disabled=true;}notify(duplicate?'這個單詞已在生詞清單。':'已加入生詞，可繼續反白下一個單詞。');}
function fields(kind,d){return kind==='vocab'?{native:d.term,chinese:d.translation}:['example','assessment-field','speaking-field','writing-field'].includes(kind)?{native:d.indigenous,chinese:d.zhHant}:kind==='grammar'?{native:d.example.indigenous,chinese:d.example.zhHant}:{native:d.text.indigenous,chinese:d.text.zhHant}}
async function task(fn){if(busy){notify('正在處理，請稍候完成。');return}busy=true;const timer=setInterval(()=>{if(!document.querySelector('[data-export-disabled]'))notify('正在等候族語服務，請保持頁面開啟，不用重複按鈕。');},12000);try{await fn()}catch(e){notify(e.message||'處理失敗，內容已保留，請稍後重試。')}finally{clearInterval(timer);busy=false;setTimeout(()=>$('#status').style.display='none',9000)}}
async function speak(text){if(!text.trim())throw Error('請先輸入族語文字。');const l={...unit.metadata.language};const key=JSON.stringify([text,l.ethnicity,l.voice]);let a=Object.values(unit.assets).find(a=>a.kind==='audio'&&a.cacheKey===key);if(!a){notify('正在合成族語語音…');const url=await synthesizeSpeech({text,ethnicity:l.ethnicity,voice:l.voice});notify('正在下載音檔…');const response=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('無法下載音檔，請再試一次。');const src=await dataURL(await normaliseAudioBlob(await response.blob()));a={id:uid(),kind:'audio',src,cacheKey:key};unit.assets[a.id]=a;save()}if(a.src.startsWith('data:application/octet-stream')){a.src=await dataURL(await normaliseAudioBlob(await (await fetch(a.src)).blob()));save()}const p=$('#player');p.hidden=false;p.src=a.src;try{await p.play();notify('正在播放。音檔已保存於教材草稿。')}catch(e){notify(playbackErrorMessage(e)+' 音檔已保存，亦可使用下方播放器。')}}
async function translate(kind,d,direction){const f=fields(kind,d),text=direction==='toNative'?f.chinese:f.native;if(!text.trim())throw Error('請先填寫要翻譯的文字。');const target=direction==='toNative'?f.native:f.chinese;notify('正在翻譯，請稍候…');const l={...unit.metadata.language};const unitId=unit.id;const rawResult=await translateText({text,ethnicity:l.ethnicity,language:l.dialect,direction});const result=direction==='toNative'?normalizeNative(rawResult):rawResult;const current=fields(kind,d);if(unit.id!==unitId||unit.metadata.language.ethnicity!==l.ethnicity||unit.metadata.language.dialect!==l.dialect||(direction==='toNative'?current.chinese:current.native)!==text||(direction==='toNative'?current.native:current.chinese)!==target)throw Error('文字或語別已修改，請重新翻譯。');if(kind==='vocab')d[direction==='toNative'?'term':'translation']=result;else if(['example','assessment-field','speaking-field','writing-field'].includes(kind))d[direction==='toNative'?'indigenous':'zhHant']=result;else (kind==='grammar'?d.example:d.text)[direction==='toNative'?'indigenous':'zhHant']=result;save();const row=document.querySelector(`[data-id="${d.id}"]`),fieldName=kind==='vocab'?(direction==='toNative'?'term':'translation'):(direction==='toNative'?'indigenous':'zhHant');const field=row?.querySelector(`[data-field="${fieldName}"]`);if(field)field.value=result;refreshSentenceAudio(d);const summary=row?.closest('.question-fold')?.querySelector('.question-fold-title');const qrow=row?.closest('.question-editor');if(summary&&qrow?.dataset.assessment){const q=unit.assessments[qrow.dataset.assessment].items.find(q=>q.id===qrow.dataset.id);summary.textContent=q.prompt.zhHant||q.prompt.indigenous||'尚未編寫';}if(['speaking-field','writing-field'].includes(kind)){const title=row?.closest('.question-fold')?.querySelector('.question-fold-title');if(title)title.textContent=d.zhHant||d.indigenous||'尚未編寫';}clearWordSelections();notify('翻譯已填入，可直接修改。')}
function refreshSentenceAudio(d){const row=document.querySelector(`[data-id="${d.id}"]`),slot=row?.querySelector('.media-slot');if(slot)slot.innerHTML=audioState(d,row.dataset.kind||'dialogue');}
async function synthesizeDialogue(d,kind='dialogue'){if(!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED,kind,entryId:d.id,firstDialogueId:unit.context.dialogues[0]?.id}))throw Error('語音合成暫停中，請使用示範入口或自己錄音。');if(!fields(kind,d).native.trim())throw Error('請先輸入族語文字。');const text=fields(kind,d).native,l={...unit.metadata.language},unitId=unit.id;notify(kind==='vocab'?'正在合成單詞語音，請稍候…':'正在合成整句語音，請稍候…');const key=JSON.stringify([text,l.ethnicity,l.voice]);let a=Object.values(unit.assets).find(a=>a.kind==='audio'&&a.cacheKey===key);if(!a){const url=await synthesizeSpeech({text,ethnicity:l.ethnicity,voice:l.voice});const res=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!res.ok)throw Error('音檔下載失敗，請再試一次。');const blob=await normaliseAudioBlob(await res.blob());if(!blob.type.startsWith('audio/'))throw Error('沒有取得有效音檔，請重新合成。');a={id:uid(),kind:'audio',src:await dataURL(blob),cacheKey:key};}if(unit.id!==unitId||fields(kind,d).native!==text||l.ethnicity!==unit.metadata.language.ethnicity||l.voice!==unit.metadata.language.voice)throw Error('文字或語別已修改，請重新合成。');unit.assets[a.id]=a;d.audio={assetId:a.id,source:'tts',textSnapshot:text,ethnicity:l.ethnicity,voice:l.voice};save();refreshSentenceAudio(d);notify('語音已準備好，按播放器即可試聽。');}
function setRecordingUI(d,active){const row=document.querySelector(`[data-id="${d.id}"]`);if(!row)return;const b=row.querySelector('[data-action="record"]'),feedback=row.querySelector('.recording-feedback');document.querySelectorAll('input,textarea,select,button').forEach(el=>{if(el===b||el.dataset.action==='cancel-recording')return;if(active){el.dataset.recordDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.recordDisabled!==undefined){el.disabled=el.dataset.recordDisabled==='true';delete el.dataset.recordDisabled;}});b.textContent=active?'停止錄音':'自己錄音';b.classList.toggle('recording',active);feedback.hidden=!active;if(active)feedback.innerHTML='<span>錄音中 · 0 秒</span><button data-action="cancel-recording">取消</button>';}
async function recordDialogue(d,kind='dialogue'){if(recordingId===d.id){recorder.stop();return;}if(recordingId||busy){notify('請先完成目前的錄音或語言服務操作。');return;}if(kind!=='speaking-field'&&!fields(kind,d).native.trim()){notify('請先填寫族語文字，再錄製聲音。');return;}document.querySelectorAll('audio').forEach(a=>a.pause());recordingId=d.id;const text=fields(kind,d).native,l={...unit.metadata.language};notify('請允許麥克風使用權限，開始錄製族語聲音。');try{await recorder.start({onStop:async blob=>{clearInterval(recordingTimer);try{if(!blob.size)throw Error('未錄到聲音，請重新錄製。');const a={id:uid(),kind:'audio',src:await dataURL(blob)};unit.assets[a.id]=a;d.audio={assetId:a.id,source:'recording',textSnapshot:text,ethnicity:l.ethnicity};save();refreshSentenceAudio(d);notify('錄音已保存，可以試聽或重新錄音。');}catch(e){notify(e.message)}finally{recordingId=null;setRecordingUI(d,false);}},onCancel:()=>{clearInterval(recordingTimer);recordingId=null;setRecordingUI(d,false);notify('已取消錄音，原有聲音保留。');},onError:e=>{clearInterval(recordingTimer);recordingId=null;setRecordingUI(d,false);notify(e.message);}});recordingStarted=Date.now();setRecordingUI(d,true);recordingTimer=setInterval(()=>{const elapsed=Math.floor((Date.now()-recordingStarted)/1000),span=document.querySelector(`[data-id="${d.id}"] .recording-feedback span`);if(span)span.textContent=`錄音中 · ${elapsed} 秒`;if(elapsed>=120)recorder.stop();},1000);notify('錄音中，完成後請按「停止錄音」。');}catch(e){recordingId=null;setRecordingUI(d,false);notify(e.message);}}
async function playDialogueAudio(d){const p=$('#player');p.hidden=false;p.src=unit.assets[d.audio.assetId].src;try{await p.play()}catch(e){notify(playbackErrorMessage(e))}}
function dataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('檔案讀取失敗'));r.readAsDataURL(blob)})}
function validate(x){if(x?.metadata?.homePractice!==undefined&&(typeof x.metadata.homePractice!=='string'||x.metadata.homePractice.length>3000))throw Error('課後小練習格式不正確或超過 3000 字元。');if(x?.metadata?.objectives!==undefined&&(typeof x.metadata.objectives!=='string'||x.metadata.objectives.length>2000))throw Error('學習目標格式不正確或超過 2000 字元。');if(!x||x.schemaVersion!=='1.0.0'||!x.metadata||!langs[x.metadata.language?.ethnicity]||!x.assets||!Array.isArray(x.context?.dialogues)||x.context.dialogues.length<6||x.context.dialogues.length>8||!Array.isArray(x.languageFocus?.vocabulary)||!Array.isArray(x.languageFocus?.grammar)||x.languageFocus.grammar.length<1||x.languageFocus.grammar.length>2)throw Error('不是支援的教材編輯檔');const l=x.metadata.language;if(!langs[l.ethnicity].languages.some(a=>a[1]===l.dialect)||!langs[l.ethnicity].voices.some(a=>a[1]===l.voice))throw Error('編輯檔的語別設定無效');const ids=new Set();for(const d of x.context.dialogues){if(typeof d.id!=='string'||ids.has(d.id)||typeof d.speaker!=='string'||typeof d.text?.indigenous!=='string'||typeof d.text?.zhHant!=='string')throw Error('對話資料不完整');ids.add(d.id)}for(const v of x.languageFocus.vocabulary)if(typeof v.id!=='string'||typeof v.term!=='string'||typeof v.translation!=='string')throw Error('生詞資料不完整');for(const g of x.languageFocus.grammar)if(typeof g.id!=='string'||typeof g.title!=='string'||typeof g.pattern!=='string'||typeof g.explanation!=='string'||(!Array.isArray(g.examples)&&(typeof g.example?.indigenous!=='string'||typeof g.example?.zhHant!=='string'))||!Array.isArray(g.sourceDialogueIds))throw Error('語法資料不完整');for(const g of x.languageFocus.grammar){if(g.examples&&(!Array.isArray(g.examples)||g.examples.length>3||g.examples.some(e=>typeof e.id!=='string'||typeof e.indigenous!=='string'||typeof e.zhHant!=='string')))throw Error('語法例句格式不正確');ensureGrammarExamples(g);}for(const a of Object.values(x.assets)){if(typeof a.src!=='string'||!(/^(data:(image\/(png|jpeg|webp)|audio\/[a-z0-9.+-]+|application\/octet-stream)(?:;[ a-z0-9=.,_-]+)*;base64,)/i.test(a.src)||/^assets\/scenes\/[a-z]+-[012]\.jpg$/.test(a.src)))throw Error('素材格式不支援：'+a.src.slice(0,45))}ensureAssessments(x);return normalizeUnitNative(x)}
async function ensureEntryAudio(item){const {entry,text}=item,l={...unit.metadata.language};let src=resolveAudio(unit,entry,text);if(src){const blob=await normaliseAudioBlob(await (await fetch(src)).blob());if(!blob.type.startsWith('audio/'))throw Error(item.label+' 的音訊格式無法辨識，請重新合成或錄製。');const current=audioIsCurrent(entry,text,l)?unit.assets[entry.audio.assetId]:null;const a=current||{id:uid(),kind:'audio'};a.src=await dataURL(blob);unit.assets[a.id]=a;entry.audio={assetId:a.id,source:current?entry.audio.source:'tts',textSnapshot:text,ethnicity:l.ethnicity,voice:l.voice};return;}if(!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED}))return;const url=await synthesizeSpeech({text,ethnicity:l.ethnicity,voice:l.voice}),res=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!res.ok)throw Error(item.label+' 語音下載失敗。');const blob=await normaliseAudioBlob(await res.blob());if(!blob.type.startsWith('audio/'))throw Error(item.label+' 未取得可用音訊。');const a={id:uid(),kind:'audio',src:await dataURL(blob),cacheKey:JSON.stringify([text,l.ethnicity,l.voice])};unit.assets[a.id]=a;entry.audio={assetId:a.id,source:'tts',textSnapshot:text,ethnicity:l.ethnicity,voice:l.voice};}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function freezeForExport(frozen){document.querySelectorAll('button,input,select,textarea').forEach(el=>{if(frozen){el.dataset.exportDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.exportDisabled!==undefined){el.disabled=el.dataset.exportDisabled==='true';delete el.dataset.exportDisabled;}});}
async function batchSynthesize(scope='all'){const entries=audioEntries(unit).filter(x=>scope!=='vocabulary'||x.kind==='vocab'),pending=entries.filter(x=>!resolveAudio(unit,x.entry,x.text));const blocked=pending.filter(x=>['recording','upload'].includes(x.entry.audio?.source));const work=pending.filter(x=>!blocked.includes(x));if(!work.length)return notify(blocked.length?'合成語音都已備妥；有 '+blocked.length+' 段老師錄音需重新確認。':'所有語音都已準備完成。');freezeForExport(true);let done=0;try{for(const item of work){notify(`正在批次合成 ${done+1} / ${work.length}：${item.label}`);await ensureEntryAudio(item);done++;save();}notify(`已完成 ${done} 段語音。${blocked.length?'另有 '+blocked.length+' 段老師錄音需重新確認，已保留原檔。':''}`);}catch(e){throw Error(`已完成 ${done} / ${work.length} 段並保存。${e.message} 再按一次會接續尚未完成的語音。`);}finally{freezeForExport(false);renderTeacherStep();}}
async function exportBook(){const issues=contentIssues(unit),entries=audioEntries(unit),l=unit.metadata.language;const staleRecordings=entries.filter(x=>['recording','upload'].includes(x.entry.audio?.source)&&(!audioIsCurrent(x.entry,x.text,l)||!unit.assets[x.entry.audio.assetId]?.src));if(staleRecordings.length)issues.push(...staleRecordings.map(x=>x.label+' 的老師錄音與目前文字或語別不一致，請重新錄音。'));if(issues.length){$('#modal').classList.remove('book-preview');bookView?.destroy();$('#modal-content').innerHTML='<h2>下載前，請先完成這些內容</h2><ul>'+issues.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>';if(!$('#modal').open)$('#modal').showModal();return;}freezeForExport(true);try{for(let i=0;i<entries.length;i++){notify(`正在準備教材語音 ${i+1} / ${entries.length}：${entries[i].label}`);await ensureEntryAudio(entries[i]);save();}const data=makeBookData(unit);if(data.image&&!data.image.startsWith('data:')){const res=await fetch(data.image);if(!res.ok)throw Error('情境圖片打包失敗。');data.image=await dataURL(await res.blob());}const html=buildBookHTML(data,{allowMissingAudio:!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED})});downloadBlob(new Blob([html],{type:'text/html;charset=utf-8'}),(unit.metadata.title||'族語教材')+'-互動課本.html');notify(!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED})?'互動課本已下載，圖片與既有音檔均已內嵌；未錄音的播放按鈕會停用，不會自動合成。':'互動課本已下載，圖片、合成語音與老師錄音都已內嵌，可離線開啟。');}catch(e){throw Error(e.message+' 已完成的音訊會保留，請稍後重試。');}finally{freezeForExport(false);[...unit.context.dialogues,...unit.languageFocus.vocabulary,...grammarEntries(unit),...assessmentFields(unit,'listening'),...speakingFields(unit)].forEach(refreshSentenceAudio);const root=$('#book-preview-root');if($('#modal').open&&root){bookView?.destroy();bookView=mountBook(root,makeBookData(unit,{includeEmptyWriting:true}));}}}
async function exportDraft(){const copy=structuredClone(unit);for(const a of Object.values(copy.assets)){if(a.src.startsWith('assets/')){a.originalSrc=a.src;const res=await fetch(a.src);if(!res.ok)throw Error('無法打包圖片');a.src=await dataURL(await res.blob())}}const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(unit.metadata.title||'族語教材')+'-編輯檔.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('編輯檔已下載，包含圖片與已合成的音訊。')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(b&&!canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED})&&(b.id==='batch-all'||['synthesize','batch-vocabulary','speak','speak-selection'].includes(b.dataset.action))){notify('語音合成暫停中，請使用「自己錄音」。');return;}if(!b){if(e.target.closest('summary')&&recordingId){e.preventDefault();notify('請先停止或取消錄音，再收合內容。');}return;}if(recordingId&&b.dataset.action!=='record'&&b.dataset.action!=='cancel-recording'){notify('請先停止或取消錄音，再進行其他操作。');return;}if(b.dataset.step){step=+b.dataset.step;renderTeacherStep();window.scrollTo(0,0);return}if(b.dataset.scene){unit.metadata.topicId=topic;const id='scene';unit.assets[id]={id,kind:'image',src:b.dataset.scene,originalSrc:b.dataset.scene,alt:'本課情境圖'};unit.context.sceneImageAssetId=id;save();renderTeacherStep();return}if(b.dataset.previewSpeak){const d=unit.context.dialogues.find(d=>d.id===b.dataset.previewSpeak);return task(()=>d.audio&&unit.assets[d.audio.assetId]?playDialogueAudio(d):speak(d.text.indigenous))}if(b.closest('#book-preview-root'))return;if(b.id==='close'){bookView?.destroy();return $('#modal').close();}if(b.id==='preview'||b.dataset.action==='preview')return renderStudentView();if(b.id==='open')return $('#import').click();if(b.id==='batch-all')return task(()=>batchSynthesize());if(b.id==='download')return task(exportDraft);if(b.id==='export-book'||b.dataset.action==='export-book')return task(exportBook);if(b.id==='new'){if(busy)return notify('請等候目前操作完成。');if(confirm('建立新單元會取代目前草稿。請先下載編輯檔備份，確定繼續？')){unit=fresh();step=1;save();renderTeacherStep()}return}const {kind,data:d}=modelFor(b),a=b.dataset.action;if(a==='toggle-cloze'){const token=clozeTokens(d.prompt.indigenous).find(t=>t.start===+b.dataset.blankStart);if(!token)return;d.blanks=validClozeBlanks(d);if(d.blanks.some(x=>x.start===token.start))d.blanks=d.blanks.filter(x=>x.start!==token.start);else{if(d.blanks.length>=2)return notify('每題最多挖空兩個單詞。');d.blanks.push(token);}save();b.closest('.cloze-controls').innerHTML=clozeControls(d);return;}if(a==='add-writing'){const type=b.dataset.writingType;if(!WRITING_TYPES.includes(type)||unit.assessments.writing.items.filter(q=>q.type===type).length>=3)return;const id=uid();unit.assessments.writing.items.push({id,type,prompt:{id:id+'_prompt',zhHant:'',indigenous:''},...(type==='cloze'?{blanks:[]}:{})});writingOpen.set(id,true);save();renderTeacherStep();return;}if(a==='remove-writing'){if(unit.assessments.writing.items.filter(q=>q.type===d.type).length<=2)return;unit.assessments.writing.items=unit.assessments.writing.items.filter(q=>q!==d);save();renderTeacherStep();return;}if(a==='add-assessment'){const category=b.dataset.assessment,items=unit.assessments[category]?.items;if(!['reading','listening'].includes(category)||items.length>=5)return;const id=uid();items.push({id});ensureAssessments(unit);questionOpen.set(id,true);save();renderTeacherStep();return;}if(a==='remove-assessment'){const category=b.closest('[data-assessment]').dataset.assessment;if(unit.assessments[category].items.length<=1)return;unit.assessments[category].items=unit.assessments[category].items.filter(q=>q!==d);save();renderTeacherStep();return;}if(a==='batch-vocabulary')return task(()=>batchSynthesize('vocabulary'));if(a==='add-speaking'&&unit.assessments.speaking.items.length<5){const id=uid();unit.assessments.speaking.items.push({id,type:'audioResponse',prompt:{id:id+'_prompt',indigenous:'',zhHant:''}});speakingOpen.set(id,true);save();renderTeacherStep();return;}else if(a==='remove-speaking'&&unit.assessments.speaking.items.length>1){unit.assessments.speaking.items=unit.assessments.speaking.items.filter(q=>q!==d);save();renderTeacherStep();return;}else if(a==='upload')return $('#image-upload').click();if(a==='upload-audio')return b.closest('[data-id]').querySelector('input[type=file]').click();if(a==='add-dialogue'&&unit.context.dialogues.length<8)unit.context.dialogues.push({id:uid(),speaker:'角色甲',text:{indigenous:'',zhHant:''}});else if(a==='remove-dialogue'&&unit.context.dialogues.length>6){if(!confirm('刪除此句？引用這句的生詞也需要重新核對。'))return;unit.context.dialogues=unit.context.dialogues.filter(x=>x!==d);for(const g of unit.languageFocus.grammar)g.sourceDialogueIds=g.sourceDialogueIds.filter(id=>id!==d.id)}else if(a==='manual-vocab'){if(unit.languageFocus.vocabulary.length>=10)return notify('生詞最多 10 個。');unit.languageFocus.vocabulary.unshift({id:uid(),term:'',translation:'',source:null});}else if(a==='add-vocab')return addSelectedVocabulary(d);else if(a==='remove-vocab')unit.languageFocus.vocabulary=unit.languageFocus.vocabulary.filter(x=>x!==d);else if(a==='add-grammar'&&unit.languageFocus.grammar.length<2)unit.languageFocus.grammar.push({id:uid(),title:'',pattern:'',explanation:'',example:{indigenous:'',zhHant:''},sourceDialogueIds:[]});else if(a==='remove-grammar'&&unit.languageFocus.grammar.length>1)unit.languageFocus.grammar=unit.languageFocus.grammar.filter(x=>x!==d);else if(a==='record')return recordDialogue(d,kind);else if(a==='cancel-recording'){recorder.cancel();return;}else if(a==='synthesize')return task(()=>synthesizeDialogue(d,kind));else if(a==='toNative'||a==='toChinese')return task(()=>translate(kind,d,a));else if(a==='speak')return task(()=>speak(fields(kind,d).native));else if(a==='speak-selection'){if(!selected||selected.dialogueId!==d.id)return notify('請先反白選取這句中的單詞。');return task(()=>speak(selected.quote))}else return;save();renderTeacherStep();if(a==='manual-vocab')document.querySelector('[data-kind=vocab] [data-field=term]')?.focus();});
document.addEventListener('change',async e=>{if(e.target.matches('.practice-audio-upload')){const f=e.target.files[0];if(!f)return;try{if(recordingId||busy)throw Error('請先完成目前操作。');if(!f.type.startsWith('audio/')||f.size>20*1024*1024)throw Error('請選擇 20 MB 以內的音檔。');const {data:d,kind}=modelFor(e.target),unitId=unit.id,ethnicity=unit.metadata.language.ethnicity;const text=fields(kind,d).native;if(!text.trim())throw Error('請先填寫這段聲音對應的族語文字。');const a={id:uid(),kind:'audio',src:await dataURL(await normaliseAudioBlob(f))};if(unit.id!==unitId||fields(kind,d).native!==text||unit.metadata.language.ethnicity!==ethnicity)throw Error('文字或語別已變更，請重新上傳音檔。');unit.assets[a.id]=a;d.audio={assetId:a.id,source:'upload',textSnapshot:text,ethnicity:unit.metadata.language.ethnicity};save();refreshSentenceAudio(d);notify('音檔已保存，可以直接試聽。');}catch(e){notify(e.message)}finally{e.target.value=''}return;}if(e.target.id==='image-upload'){const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024)return notify('請選擇 10 MB 以內的 PNG、JPG 或 WebP 圖片。');try{const src=await dataURL(f);unit.assets.scene={id:'scene',kind:'image',src,alt:f.name};unit.context.sceneImageAssetId='scene';save();renderTeacherStep()}catch(e){notify(e.message)}}else if(e.target.id==='import'){const f=e.target.files[0];if(!f)return;try{if(busy||recordingId)throw Error('請等候目前操作完成。');if(f.size>100*1024*1024)throw Error('編輯檔超過 100 MB');const next=validate(JSON.parse(await f.text()));if(!confirm('開啟編輯檔會取代目前草稿，確定繼續？'))return;unit=next;topic=unit.metadata.topicId||scene().match(/scenes\/([a-z]+)-/)?.[1]||'intro';step=1;save();renderTeacherStep();notify('已開啟教材，可繼續編輯。')}catch(e){notify('無法開啟：'+e.message)}finally{e.target.value=''}}});
window.addEventListener('beforeunload',e=>{if(busy||recordingId){e.preventDefault();e.returnValue=''}});
init();

function homeworkView(){return `<section class="panel homework-panel"><h2>課後小練習（選填）</h2><p class="muted">延伸整個單元的學習，將本課詞句用在生活中，完成後在下次上課分享。</p><label>任務說明<textarea rows="4" maxlength="3000" data-meta="homePractice" placeholder="例如：用本課句型訪問一位家人，介紹對方喜歡的活動。">${esc(unit.metadata.homePractice||'')}</textarea></label></section><div class="step-footer"><button data-step="7">上一關：寫作練習</button><button class="preview-button" data-action="preview">預覽本課教材</button></div>`;}

function applySpeechAvailability(){const notice=$('#speech-notice');if(notice){notice.hidden=false;notice.textContent=canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED})?'單句與批次語音合成已開放；下載時會補齊缺少的語音，並保留老師錄音。':'語音合成暫停中，可使用「自己錄音」；既有音檔仍可播放，下載時不會自動合成。';}if(canSynthesizeEntry({enabled:CONFIG.TTS_ENABLED}))return;document.querySelectorAll('#batch-all,[data-action="synthesize"],[data-action="batch-vocabulary"]').forEach(b=>{b.disabled=true;b.title='語音合成暫停中，請使用自己錄音';if(!b.textContent.endsWith('（暫停）'))b.textContent+='（暫停）';});}
